const fs=require('fs');const p='admin-workstation.html';let s=fs.readFileSync(p,'utf8');const a=`oninput="setCaseSearch(this.value, 'dashboard')"`;const b=`oninput="setCaseSearch(this.value, 'workstation')"`;if(!s.includes(a)||!s.includes(b)) throw new Error('handlers not found');s=s.replace(a,`oninput="setCaseSearch(this.value, &quot;dashboard&quot;)"`);s=s.replace(b,`oninput="setCaseSearch(this.value, &quot;workstation&quot;)"`);fs.writeFileSync(p,s);